add_action( 'woocommerce_after_checkout_billing_form', 'perfectpixel_checkout_user_url_field' );
add_action( 'woocommerce_checkout_update_user_meta', 'perfectpixel_checkout_user_url_save', 10, 2 );

function perfectpixel_checkout_user_url_field( $checkout ) {
	$current = is_user_logged_in() ? wp_get_current_user()->user_url : '';
	woocommerce_form_field(
		'perfectpixel_user_url',
		array(
			'type'        => 'url',
			'label'       => '{{website_label}}',
			'required'    => false,
			'class'       => array( 'form-row-wide' ),
			'placeholder' => 'https://',
		),
		$checkout->get_value( 'perfectpixel_user_url' ) ? $checkout->get_value( 'perfectpixel_user_url' ) : $current
	);
}

function perfectpixel_checkout_user_url_save( $customer_id, $posted ) {
	if ( $customer_id && ! empty( $_POST['perfectpixel_user_url'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		wp_update_user(
			array(
				'ID'       => $customer_id,
				'user_url' => esc_url_raw( wp_unslash( $_POST['perfectpixel_user_url'] ) ), // phpcs:ignore WordPress.Security.NonceVerification
			)
		);
	}
}
